from django.conf import settings

settings.configure(
    SECRET_KEY="new-secret-key-0123456789",
    SECRET_KEY_FALLBACKS=["old-secret-key-0123456789"],
    AUTHENTICATION_BACKENDS=["repro_duck_user.Backend"],
    INSTALLED_APPS=["django.contrib.auth", "django.contrib.contenttypes"],
    DATABASES={},
)
django.setup()

from django.contrib.auth import (
    BACKEND_SESSION_KEY, HASH_SESSION_KEY, SESSION_KEY, get_user,
)


class DuckUser:
    """Documented: a user that implements its own get_session_auth_hash()."""
    pk = 1
    is_authenticated = True

    def get_session_auth_hash(self):
        return "current-hash"


class Backend:
    def get_user(self, user_id):
        return DuckUser()


class Session(dict):
    flushed = False

    def flush(self):
        self.clear()
        self.flushed = True

    def cycle_key(self):
        pass


